from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError, ResponseValidationError
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

@app.get("/test-request")
async def test_request(item_id: int):
    return {"item_id": item_id}

@app.get("/test-response")
async def test_response():
    # This should trigger ResponseValidationError because it returns a dict instead of an int
    # But we need a response model for that.
    return {"id": "not-an-int"}

# To trigger ResponseValidationError, we need a response_model
@app.get("/test-response-model", response_model={"id": int})
async def test_response_model():
    return {"id": "not-an-int"}

client = TestClient(app)

def test_request_validation_error():
    try:
        client.get("/test-request", params={"item_id": "invalid"})
    except RequestValidationError as exc:
        print(f"Caught RequestValidationError:\n{exc}")
        assert "test_request" in str(exc)
        assert "GET /test-request" in str(exc)
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e

def test_response_validation_error():
    try:
        client.get("/test-response-model")
    except ResponseValidationError as exc:
        print(f"Caught ResponseValidationError:\n{exc}")
        assert "test_response_model" in str(exc)
        assert "GET /test-response-model" in str(exc)
    except Exception as e:
        print(f"Caught unexpected exception: {type(e).__name__}: {e}")
        raise e

if __name__ == "__main__":
    test_request_validation_error()
    test_response_validation_error()

